setFilter('a'); // request A
setFilter('b'); // request B
// B resolves, then A resolves and overwrites B

useEffect(() => {
  const controller = new AbortController();
  loadLessons(filter, controller.signal)
    .then(setLessons)
    .catch(error => {
      if (error.name !== 'AbortError') setError(error.message);
    });
  return () => controller.abort();
}, [filter]);

const requestId = ++latestRequest.current;
const result = await loadLessons(filter);
if (requestId === latestRequest.current) {
  setLessons(result);
  setLoading(false);
}

resolveB([{ title: 'B sonucu' }]);
await screen.findByText('B sonucu');
resolveA([{ title: 'A sonucu' }]);
expect(screen.queryByText('A sonucu')).not.toBeInTheDocument();
